 for(const key of Object.keys(choices)){if(!Array.isArray(choices[key]))throw Error('Invalid selections');if(choices[key].length&&!(d.posOptions118||[]).some(g=>g.id===key))throw Error(d.name+': customization changed');}let lines=[...(d.recipe||[])],picked=0;for(const g of d.posOptions118||[]){const ids=choices[g.id]||[];if(!Array.isArray(ids)||new Set(ids).size!==ids.length||ids.length<Number(g.min||0)||ids.length>Number(g.max??g.options.length))throw Error(d.name+': check '+g.name+' selections');if(ids.length&&(g.replaces||[]).length)lines=lines.filter(l=>!g.replaces.includes(l.itemId));for(const oid of ids){const o=g.options.find(o=>o.id===oid);if(!o||o.available===false)throw Error('Selected option is unavailable');if(g.id!=='wellness')picked++;if(!o.recipe?.length&&!o.posNoStock118)throw Error(o.name+': set ingredient quantities');lines.push(...(o.recipe||[]));}}
